import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // STAGE: Backdrop with engineered gradient
  // ============================================================================
  const backdropGroup = new THREE.Group();

  // Parse colors from config
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Create backdrop plane (7x6 units at z=-2.5)
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colors.surface),
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = -10;
  backdropGroup.add(backdrop);

  // ============================================================================
  // PRIMARY CTA: Textured plane with orb-decor image
  // ============================================================================
  const ctaGroup = new THREE.Group();

  // Load the orb-decor texture
  let textureLoaded = false;
  const planeGeo = new THREE.PlaneGeometry(1.2, 1.2);
  const planeMat = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    transparent: true,
    side: THREE.DoubleSide,
  });
  const plane = new THREE.Mesh(planeGeo, planeMat);

  // Async load and apply texture
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        planeMat.map = tex;
        planeMat.needsUpdate = true;
        textureLoaded = true;
      })
      .catch(() => {
        console.warn('Failed to load orb-decor texture:', config.imageUrl);
      });
  }

  plane.position.copy(
    new THREE.Vector3(
      config.scenePosition?.[0] ?? 0,
      config.scenePosition?.[1] ?? -2.85,
      config.scenePosition?.[2] ?? 0.2
    )
  );
  plane.rotation.order = 'XYZ';

  if (config.scenePosition) {
    plane.position.set(
      config.scenePosition[0] ?? 0,
      config.scenePosition[1] ?? -2.85,
      config.scenePosition[2] ?? 0.2
    );
  }

  ctaGroup.add(plane);

  // ============================================================================
  // COMPOSITION: Root group
  // ============================================================================
  const root = new THREE.Group();
  root.add(backdropGroup);
  root.add(ctaGroup);

  // ============================================================================
  // CLEANUP & HANDLERS
  // ============================================================================
  const primitiveCleanups = [];

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Kill all primitive timelines
    for (const cleanup of primitiveCleanups) {
      if (cleanup && typeof cleanup === 'function') {
        cleanup();
      }
    }
    primitiveCleanups.length = 0;

    // Dispose materials and geometries
    backdropMat.dispose();
    backdropGeo.dispose();
    planeMat.dispose();
    if (planeMat.map) {
      planeMat.map.dispose();
    }
    planeGeo.dispose();
  };

  return root;
}
